const listUserChallengeVotes = `-- name: ListUserChallengeVotes :many
SELECT entry_id FROM challenge_votes
WHERE challenge_id = $1 AND user_id = $2
ORDER BY created_at
`

type ListUserChallengeVotesParams struct {
	ChallengeID string `json:"challenge_id"`
	UserID      string `json:"user_id"`
}

func (q *Queries) ListUserChallengeVotes(ctx context.Context, arg ListUserChallengeVotesParams) ([]string, error) {
	rows, err := q.db.Query(ctx, listUserChallengeVotes, arg.ChallengeID, arg.UserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var entry_id string
		if err := rows.Scan(&entry_id); err != nil {
			return nil, err
		}
		items = append(items, entry_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

