const lockVoter = `-- name: LockVoter :one
SELECT users.id, users.created_at,
       EXISTS (
           SELECT 1 FROM user_bans
           WHERE user_bans.user_id = users.id AND ban_active(user_bans)
       )::boolean AS banned
FROM users
WHERE users.id = $1 AND users.deleted_at IS NULL
FOR UPDATE OF users
`

type LockVoterRow struct {
	ID        string             `json:"id"`
	CreatedAt pgtype.Timestamptz `json:"created_at"`
	Banned    bool               `json:"banned"`
}

// The voter's row lock serializes their votes, so the per-challenge limit
// holds; also whether they may vote at all.
func (q *Queries) LockVoter(ctx context.Context, id string) (LockVoterRow, error) {
	row := q.db.QueryRow(ctx, lockVoter, id)
	var i LockVoterRow
	err := row.Scan(&i.ID, &i.CreatedAt, &i.Banned)
	return i, err
}

